import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"I/Q 合成器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/iq_combine/index.md","filePath":"v0.2.0-alpha/modules/iq_combine/index.md"}'),r={name:"v0.2.0-alpha/modules/iq_combine/index.md"};function i(h,t,l,n,c,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="i-q-合成器" tabindex="-1">I/Q 合成器 <a class="header-anchor" href="#i-q-合成器" aria-label="Permalink to &quot;I/Q 合成器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>iq_combine</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>把两路实数坐标组合为一个复数样本：<code>z = I + jQ</code>。它是数据表示转换，便于将独立构造的两个分量送入复数运算和星座观察。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>I路实数输出 → I/Q 合成器.i</code>，<code>Q路实数输出 → I/Q 合成器.q</code>，从 <code>out</code> 取得复数流。两路都需要接线，并具有相同的 item 速率和向量长度。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>i</code>（I）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>q</code>（Q）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（复数输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>向量长度表示每个 item 含多少个坐标对。第 k 个 I 分量与同一 item 的第 k 个 Q 分量组合，不会先发送所有 I 再发送所有 Q。</p><p>合成器不产生正交相位，也不进行载波调制。若两路原本是任意信号，输出就表达这两个实际坐标；需要正交波形时，应在上游明确构造。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>向量长度影响端口形状，修改后重新准备。运行中改变上游信号参数，可以观察新坐标形成的轨迹；不能通过合成器把不同采样率隐式对齐。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例先分解复数加法器输出，再将 I 和 Q 接回合成器。观察合成输出应与分解前的复数流一致，说明这次往返仅改变表示方式。另可只观察某个分量，核对对应关系。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么合成后没有圆形轨迹？</strong> 圆形需要特定幅度与相位关系，合成器只保留输入的实际 I/Q。</p><p><strong>能只接 I 吗？</strong> 当前图要求所声明输入完整连接；需要 Q 为零时，明确连接同速率的零信号。</p>',26)])])}const b=e(r,[["render",i]]);export{m as __pageData,b as default};
